const ok = (res, data, meta) => res.json({ success: true, data, ...(meta ? { meta } : {}) });
const fail = (res, status, message, details) => res.status(status).json({ success: false, error: message, ...(details ? { details } : {}) });
const failCode = (res, status, code, message, details) => res.status(status).json({ success: false, code, error: message, ...(details ? { details } : {}) });
const positiveInt = value => Number.isInteger(Number(value)) && Number(value) > 0;
const adminOnly = (req, res, next) => { if (!process.env.ADMIN_TOKEN || req.get('x-admin-token') !== process.env.ADMIN_TOKEN) return fail(res, 401, 'Akses admin tidak sah'); next(); };
const analyticsRateLimit = rateLimit(60_000, Number(process.env.ANALYTICS_TRACK_PER_MINUTE || 120));
const normalizeEmail = value => { const email = String(value || '').trim().toLowerCase(); return /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email) && email.length <= 254 ? email : null; };
const maskEmail = email => { const [local, domain] = String(email || '').split('@'); return local && domain ? `${local.slice(0, 2)}***@${domain}` : 'email tersamarkan'; };
const sendEmailOtp = async (email, code) => { const provider = String(process.env.EMAIL_PROVIDER || 'generic').toLowerCase(); const isResend = provider === 'resend'; const url = isResend ? 'https://api.resend.com/emails' : process.env.EMAIL_PROVIDER_URL; const token = isResend ? (process.env.RESEND_API_KEY || process.env.EMAIL_PROVIDER_TOKEN) : process.env.EMAIL_PROVIDER_TOKEN; if (!url || !process.env.EMAIL_FROM || (isResend && !token)) return false; const payload = { from: process.env.EMAIL_FROM, to: isResend ? [email] : email, reply_to: process.env.EMAIL_REPLY_TO || undefined, subject: 'Kode verifikasi SultraKita', text: `Kode verifikasi SultraKita Anda adalah ${code}. Kode berlaku selama 5 menit. Jangan bagikan kode ini kepada siapa pun.`, html: `<p>Kode verifikasi SultraKita Anda adalah <strong>${code}</strong>.</p><p>Kode berlaku selama 5 menit. Jangan bagikan kode ini kepada siapa pun.</p>` }; const response = await fetch(url, { method:'POST', headers:{ 'content-type':'application/json', ...(token ? { authorization:`Bearer ${token}` } : {}) }, body:JSON.stringify(payload) }); if (!response.ok) { const detail = await response.text().catch(()=>''); throw new Error(`Provider email gagal mengirim OTP (${response.status}): ${detail.slice(0, 200)}`); } return true; };
const sendOtp = async (channel, destination, code) => { if (channel === 'email') return sendEmailOtp(destination, code); const whatsappConfigured = Boolean(process.env.WHATSAPP_ACCESS_TOKEN && process.env.WHATSAPP_PHONE_NUMBER_ID && process.env.WHATSAPP_OTP_TEMPLATE_NAME); if (whatsappConfigured) return sendWhatsAppOtp(destination, code); if (!process.env.OTP_PROVIDER_URL) return false; const response = await fetch(process.env.OTP_PROVIDER_URL, { method:'POST', headers:{ 'content-type':'application/json', ...(process.env.OTP_PROVIDER_TOKEN ? { authorization:`Bearer ${process.env.OTP_PROVIDER_TOKEN}` } : {}) }, body:JSON.stringify({ phone: normalizeWhatsAppPhone(destination), code, channel:'whatsapp' }) }); if (!response.ok) throw new Error('Provider OTP WhatsApp gagal mengirim kode'); return true; };
const normalizeWhatsAppPhone = phone => { const digits = String(phone || '').replace(/\D/g, ''); if (digits.startsWith('08')) return `62${digits.slice(1)}`; if (digits.startsWith('8')) return `62${digits}`; if (digits.startsWith('62')) return digits; return null; };
const sendWhatsAppOtp = async (phone, code) => { const to = normalizeWhatsAppPhone(phone); if (!to) return false; const version = process.env.WHATSAPP_API_VERSION || 'v23.0'; const components = [{ type:'body', parameters:[{ type:'text', text:String(code) }] }]; const response = await fetch(`https://graph.facebook.com/${version}/${process.env.WHATSAPP_PHONE_NUMBER_ID}/messages`, { method:'POST', headers:{ authorization:`Bearer ${process.env.WHATSAPP_ACCESS_TOKEN}`, 'content-type':'application/json' }, body:JSON.stringify({ messaging_product:'whatsapp', recipient_type:'individual', to, type:'template', template:{ name:process.env.WHATSAPP_OTP_TEMPLATE_NAME, language:{ code:process.env.WHATSAPP_OTP_TEMPLATE_LANGUAGE || 'id' }, components } }) }); if (!response.ok) { const detail = await response.text().catch(()=>''); throw new Error(`WhatsApp OTP gagal dikirim (${response.status}): ${detail.slice(0, 200)}`); } return true; };
const sendWhatsAppText = async (phone, body) => { const to = normalizeWhatsAppPhone(phone); if (!to || !process.env.WHATSAPP_ACCESS_TOKEN || !process.env.WHATSAPP_PHONE_NUMBER_ID) return { sent:false, reason:'not_configured' }; const version = process.env.WHATSAPP_API_VERSION || 'v23.0'; const response = await fetch(`https://graph.facebook.com/${version}/${process.env.WHATSAPP_PHONE_NUMBER_ID}/messages`, { method:'POST', headers:{ authorization:`Bearer ${process.env.WHATSAPP_ACCESS_TOKEN}`, 'content-type':'application/json' }, body:JSON.stringify({ messaging_product:'whatsapp', recipient_type:'individual', to, type:'text', text:{ preview_url:false, body:String(body).slice(0, 3500) } }) }); if (!response.ok) { const detail = await response.text().catch(()=>''); throw new Error(`WhatsApp provider gagal mengirim notifikasi (${response.status}): ${detail.slice(0, 200)}`); } return { sent:true }; };
const sendWhatsAppTemplate = async (phone, variables) => { const to = normalizeWhatsAppPhone(phone); if (!to || !process.env.WHATSAPP_ACCESS_TOKEN || !process.env.WHATSAPP_PHONE_NUMBER_ID || !process.env.WHATSAPP_TEMPLATE_NAME) return { sent:false, reason:'template_not_configured' }; const version = process.env.WHATSAPP_API_VERSION || 'v23.0'; const components = [{ type:'body', parameters:Object.values(variables).slice(0, 4).map(value => ({ type:'text', text:String(value ?? '-').slice(0, 900) })) }]; const response = await fetch(`https://graph.facebook.com/${version}/${process.env.WHATSAPP_PHONE_NUMBER_ID}/messages`, { method:'POST', headers:{ authorization:`Bearer ${process.env.WHATSAPP_ACCESS_TOKEN}`, 'content-type':'application/json' }, body:JSON.stringify({ messaging_product:'whatsapp', recipient_type:'individual', to, type:'template', template:{ name:process.env.WHATSAPP_TEMPLATE_NAME, language:{ code:process.env.WHATSAPP_TEMPLATE_LANGUAGE || 'id' }, components } }) }); if (!response.ok) { const detail = await response.text().catch(()=>''); throw new Error(`Template WhatsApp gagal dikirim (${response.status}): ${detail.slice(0, 200)}`); } return { sent:true }; };
const parseCookies = header => Object.fromEntries(String(header || '').split(';').map(part => part.trim().split('=').map(decodeURIComponent)).filter(pair => pair.length === 2));
const issueSession = async userId => { const token = crypto.randomBytes(32).toString('hex'); const tokenHash = crypto.createHash('sha256').update(token).digest('hex'); await run('INSERT INTO sessions (token_hash, user_id, expires_at) VALUES (?, ?, ?)', [tokenHash, userId, Date.now() + 30 * 24 * 60 * 60 * 1000]); return token; };
const googleRedirectUri = () => process.env.GOOGLE_REDIRECT_URI || `${SITE_URL}/api/auth/google/callback`;
const googleConfigured = () => Boolean(process.env.GOOGLE_CLIENT_ID && process.env.GOOGLE_CLIENT_SECRET);
const notifySellerWhatsApp = async ({ phone, sellerName, listingTitle, senderName, message, channel='pertanyaan' }) => { if (!phone) return; try { const result = await sendWhatsAppTemplate(phone, { sellerName, listingTitle, senderName, message }); if (result.reason === 'template_not_configured') console.info('[whatsapp-notification] template belum dikonfigurasi; notifikasi dilewati'); } catch (error) { console.error('[whatsapp-notification]', error.message); } };
const externalFeedCache = new Map();
const parseFeedConfig = raw => { try { const parsed = JSON.parse(raw || '[]'); return Array.isArray(parsed) ? parsed.filter(feed => feed && feed.id && /^https:\/\//.test(feed.url)).slice(0, 10) : []; } catch { return []; } };
const pickPath = (value, pathText) => String(pathText || '').split('.').filter(Boolean).reduce((current, key) => current && current[key], value);
const normalizeExternalItem = (feed, item) => { const row = item || {}; const title = row.title || row.name || row.product_name; const url = row.url || row.link || row.product_url; if (!title || !url || !/^https:\/\//.test(String(url))) return null; return { external_id: String(row.id || row.external_id || crypto.createHash('sha256').update(`${feed.id}:${title}:${url}`).digest('hex').slice(0, 20)), source: feed.id, source_label: feed.label || feed.id, title: String(title).slice(0, 180), category: String(row.category || feed.category || 'Lainnya').slice(0, 80), city: String(row.city || row.location || 'Kendari').slice(0, 80), province: 'Sulawesi Tenggara', price: Number.isFinite(Number(row.price)) ? Number(row.price) : null, image_url: /^https:\/\//.test(String(row.image_url || row.image || '')) ? String(row.image_url || row.image).slice(0, 500) : null, is_demo: false, provenance: 'partner_api_or_feed', observed_at: new Date().toISOString(), url: String(url).slice(0, 1000) }; };
const loadExternalListings = async () => { const feeds = parseFeedConfig(process.env.EXTERNAL_MARKETPLACE_FEEDS_JSON); if (!feeds.length) return { data: [], meta: { live_sync: false, configured_feeds: 0, notice: 'Belum ada API/feed marketplace resmi yang dikonfigurasi.' } }; const all = []; const statuses = []; for (const feed of feeds) { const cached = externalFeedCache.get(feed.id); if (cached && cached.expires > Date.now()) { all.push(...cached.data); statuses.push({ id: feed.id, status: 'cache' }); continue; } const controller = new AbortController(); const timer = setTimeout(() => controller.abort(), 4500); try { const headers = { accept: 'application/json', ...(feed.auth_env && process.env[feed.auth_env] ? { [feed.auth_header || 'authorization']: feed.auth_header?.toLowerCase() === 'authorization' ? `Bearer ${process.env[feed.auth_env]}` : process.env[feed.auth_env] } : {}) }; const response = await fetch(feed.url, { headers, signal: controller.signal }); if (!response.ok) throw new Error(`HTTP ${response.status}`); const payload = await response.json(); const items = pickPath(payload, feed.items_path || 'items'); const rows = (Array.isArray(items) ? items : []).map(item => normalizeExternalItem(feed, item)).filter(Boolean).slice(0, 100); externalFeedCache.set(feed.id, { data: rows, expires: Date.now() + 60_000 }); all.push(...rows); statuses.push({ id: feed.id, status: 'ok', count: rows.length }); } catch (error) { statuses.push({ id: feed.id, status: 'error', message: error.name === 'AbortError' ? 'timeout' : 'unavailable' }); } finally { clearTimeout(timer); } } return { data: all, meta: { live_sync: true, configured_feeds: feeds.length, feeds: statuses } }; };

