app.post('/api/conversations/:id/messages', async (req, res, next) => { try { const { sender_id, body } = req.body || {}; if (!positiveInt(sender_id) || !body || body.trim().length < 1 || body.trim().length > 2000) return fail(res, 422, 'sender_id dan pesan belum valid'); if (!req.user) return fail(res, 401, 'Autentikasi diperlukan'); if (Number(req.user.id) !== Number(sender_id) && req.user.role !== 'admin') return fail(res, 403, 'Identitas pengirim tidak sesuai session'); const conversations = await query('SELECT c.*, l.title AS listing_title, seller.name AS seller_name, seller.phone AS seller_phone FROM conversations c LEFT JOIN listings l ON l.id = c.listing_id LEFT JOIN users seller ON seller.id = c.seller_id WHERE c.id = ?', [Number(req.params.id)]); if (!conversations.length) return fail(res, 404, 'Percakapan tidak ditemukan'); const conversation = conversations[0]; if (conversation.status !== 'open') return fail(res, 409, 'Percakapan sudah ditutup'); const created = await run('INSERT INTO messages (conversation_id, sender_id, body) VALUES (?, ?, ?)', [Number(req.params.id), Number(req.user.id), body.trim()]); await run('UPDATE conversations SET updated_at = CURRENT_TIMESTAMP WHERE id = ?', [Number(req.params.id)]); const [message] = await query('SELECT m.*, u.name AS sender_name FROM messages m JOIN users u ON u.id = m.sender_id WHERE m.id = ?', [created.id]); if (Number(sender_id) === Number(conversation.buyer_id)) void notifySellerWhatsApp({ phone:conversation.seller_phone, sellerName:conversation.seller_name, listingTitle:conversation.listing_title, senderName:message.sender_name, message:message.body, channel:'pesan pembeli' }); res.status(201); ok(res, message); } catch (error) { next(error); } });
app.get('/api/conversations/:id/stream', async (req, res) => { if (!positiveInt(req.params.id)) return res.status(400).end(); res.setHeader('Content-Type', 'text/event-stream'); res.setHeader('Cache-Control', 'no-cache'); res.setHeader('Connection', 'keep-alive'); res.flushHeaders?.(); res.write(': connected\n\n'); let lastId = Number(req.query.after || 0); const timer = setInterval(async () => { try { const rows = await query('SELECT m.*, u.name AS sender_name FROM messages m JOIN users u ON u.id = m.sender_id WHERE m.conversation_id = ? AND m.id > ? ORDER BY m.id ASC', [Number(req.params.id), lastId]); for (const message of rows) { lastId = message.id; res.write(`data: ${JSON.stringify(message)}\\n\\n`); } } catch { clearInterval(timer); res.end(); } }, 2000); req.on('close', () => clearInterval(timer)); });

