app.get('/api/analytics/summary', requireRole('admin'), adminOnly, async (req, res, next) => { try { const days = Math.min(90, Math.max(1, Number(req.query.days) || 7)); const [totals] = await query("SELECT COUNT(*) AS events, COUNT(*) FILTER (WHERE event_name = 'page_view') AS page_views, COUNT(*) FILTER (WHERE event_name = 'listing_view') AS listing_views, COUNT(*) FILTER (WHERE event_name = 'search') AS searches, COUNT(*) FILTER (WHERE event_name = 'listing_contact') AS contacts FROM analytics_events WHERE created_at >= now() - (? * interval '1 day')", [`-${days} days`]); const topListings = await query("SELECT l.id, l.title, l.views, COUNT(a.id) AS tracked_views FROM listings l LEFT JOIN analytics_events a ON a.listing_id = l.id AND a.event_name = 'listing_view' AND a.created_at >= now() - (? * interval '1 day') GROUP BY l.id ORDER BY tracked_views DESC, l.views DESC LIMIT 10", [`-${days} days`]); const daily = await query("SELECT created_at::date AS date, COUNT(*)::int AS events, COUNT(*) FILTER (WHERE event_name = 'page_view')::int AS page_views, COUNT(*) FILTER (WHERE event_name = 'listing_view')::int AS listing_views FROM analytics_events WHERE created_at >= now() - (? * interval '1 day') GROUP BY created_at::date ORDER BY date ASC", [`-${days} days`]); ok(res, { days, totals, top_listings: topListings, daily }); } catch (error) { next(error); } });

